scripting:execute.scripting:code:
def xml = new groovy.util.XmlSlurper(false, false).parseText(payload.toString())
def body = xml.Body
def first = body.children().find{ true } // первый элемент внутри Body

if (first == null) {
  message.setPayload(null)
  return
}

// Проверка на error
def err = first.'error'
if (err && err.size() > 0) {
  def errorsList = []
  if (err.errors && err.errors.error) {
    err.errors.error.each { e -> errorsList << (e.text() ?: "") }
  }
  message.setPayload([
    timestamp: (err.timestamp?.text() ?: ""),
    message  : (err.message?.text() ?: ""),
    errors   : errorsList
  ])
  return
}

// Парсинг flat (если есть)
def f = first.'flat'
if (f && f.size() > 0) {
  def coord = f.coordinates
  def house = f.house
  message.setPayload([
    id              : (f.id?.text() ? f.id.text().toInteger() : null),
    creationDate    : (f.creation_date?.text() ?: null),
    name            : (f.name?.text() ?: null),
    coordinates     : [
      x: (coord?.x?.text() ? coord.x.text().toInteger() : null),
      y: (coord?.y?.text() ? new BigDecimal(coord.y.text()) : null)
    ],
    area            : (f.area?.text() ? f.area.text().toInteger() : null),
    number_of_rooms : (f.number_of_rooms?.text() ? f.number_of_rooms.text().toInteger() : null),
    living_space    : (f.living_space?.text() ? new BigDecimal(f.living_space.text()) : null),
    price           : (f.price?.text() ? f.price.text().toInteger() : null),
    has_balcony     : (f.has_balcony?.text() ? f.has_balcony.text().toBoolean() : null),
    furnish         : (f.furnish?.text() ?: null),
    transport       : (f.transport?.text() ?: null),
    house           : [ name: (house?.name?.text() ?: null) ]
  ])
  return
}

// ни error ни flat
message.setPayload(null)

